/**
 * Service registry used to resolve services by name without importing UseService.
 * Breaks circular dependency: UseService → ServiceImp → UseService.
 *
 * Service constructors must be synchronous. Re-entrant getService(name) while
 * the same service is being created will throw.
 */
export declare function registerService(name: string, Impl: new () => unknown): void;
export declare function getService<T>(name: string): T;
